//! 🔍️ One genuine Flow caller retains trace input, exact JSON output and every pending close owner.
use super::*;
use semio_framework_2d_engine::PathSegment;
use semio_framework_2d_trace::{BitmapTraceInput,BitmapTraceJob,BitmapTraceError};
use semio_framework_value::{work::RetainedWorkLedger,RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,ValueError,ValueRefusalKind,retirement::controlled::ControlledRetirement};
use semio_framework_pack_json::{ArtifactCanonicalJsonTree as Tree,ArtifactCanonicalJsonNode as Node,ArtifactCanonicalJsonText as Text,ArtifactCanonicalJsonTreeWireCursor};
pub(super) fn abi_refusal(code:AbiErrorCode)->FlowFailure{let message=match code{AbiErrorCode::Cancelled=>"Cancelled",AbiErrorCode::Interrupted=>"Interrupted",AbiErrorCode::DeadlineExceeded=>"DeadlineExceeded",AbiErrorCode::NoCredit=>"NoCredit",_=>unreachable!("selected Flow trace lifecycle code")};FlowFailure::from_value(code,ValueError::literal(ValueRefusalKind::WorkLimit,message))}
fn refusal(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
fn permits(grant:RetainedCloneGrant,d:RetirementDemand)->bool{grant.maximum_items>0&&grant.maximum_copy_bytes>=d.copy_bytes&&grant.maximum_capacity_bytes>=d.capacity_bytes&&grant.maximum_release_bytes>=d.release_bytes&&grant.maximum_depth>=d.depth}
fn slot<T>(values:&mut Vec<T>,work:&mut RetainedWorkLedger,effect:&mut semio_framework_value::RetainedAllocationEffect<'_>)->Result<bool,ValueError>{let target=if values.len()==values.capacity(){values.capacity().checked_mul(2).ok_or_else(||refusal("Flow trace capacity overflow"))?.max(16)}else{values.len()+1};if !work.reserve_vec(values,target,effect.actual()).map_err(refusal)?{return Ok(false);}work.vec_slot(values).map_err(refusal)}
fn u32_arg(args:&FlowArguments,key:&str)->Result<u32,ValueError>{let span=args.get(key).ok_or_else(||refusal("Original trace argument absent"))?;let raw:[u8;4]=args.bytes(span).try_into().map_err(|_|refusal("Original trace integer extent changed"))?;Ok(u32::from_le_bytes(raw))}
fn f64_arg(args:&FlowArguments,key:&str)->Result<f64,ValueError>{let span=args.get(key).ok_or_else(||refusal("Original trace argument absent"))?;let raw:[u8;8]=args.bytes(span).try_into().map_err(|_|refusal("Original trace scalar extent changed"))?;Ok(f64::from_le_bytes(raw))}
fn fault_message(error:BitmapTraceError)->&'static str{match error{BitmapTraceError::Invalid(message)=>message,BitmapTraceError::Incomplete=>"Bitmap trace incomplete",BitmapTraceError::Cancelled=>"Bitmap trace cancelled"}}
#[derive(semio_framework_value::CanonicalJsonTree,semio_framework_value::RetireOwned)]
#[canonical_json(owner=semio_framework_pack_json)]
#[value(tag="kind",rename_all="camelCase")]
enum TraceSegment{Move{to:[f64;2]},Line{to:[f64;2]},Close}
#[derive(semio_framework_value::RetireOwned)]
enum TraceWire{Success{segments:Vec<TraceSegment>},Failure{error:String}}
impl Tree for TraceWire{
 fn canonical_tree_node(&self)->Result<Node<'_>,ValueError>{Ok(Node::Object(1))}
 fn canonical_tree_key(&self,ordinal:usize)->Result<Text<'_>,ValueError>{if ordinal!=0{return Err(refusal("Trace wire key ordinal changed"));}Ok(match self{Self::Success{..}=>"segments".into(),Self::Failure{..}=>"error".into()})}
 fn canonical_tree_child(&self,ordinal:usize)->Result<&dyn Tree,ValueError>{if ordinal!=0{return Err(refusal("Trace wire child ordinal changed"));}Ok(match self{Self::Success{segments}=>segments,Self::Failure{error}=>error})}
}
#[derive(semio_framework_value::RetireOwned)]
struct TraceOwners{mask:Vec<u8>,segments:Vec<TraceSegment>,message:String,output:Option<Vec<u8>>,child_refusal:Option<ValueError>,bookkeeping_refusal:Option<ValueError>}
struct TraceStep{cpu:u64}
impl TraceStep{fn work(cpu:u64)->Self{Self{cpu}}}
pub(crate) struct FlowTraceCursor{
 identity:Option<(u64,u64)>,phase:u8,width:u32,height:u32,threshold:f64,epsilon:f64,mask_length:usize,at:usize,mask:Vec<u8>,tracer:Option<BitmapTraceJob<Vec<u8>>>,trace_close:Option<ControlledRetirement<BitmapTraceJob<Vec<u8>>>>,segments:Vec<TraceSegment>,encoding:Option<ArtifactCanonicalJsonTreeWireCursor<TraceWire>>,fault:Option<(bool,&'static str)>,fault_part:u8,fault_at:usize,message:String,owners:Option<ControlledRetirement<TraceOwners>>,pending:RetirementDemand,receipt:RetainedCloneProgress,last_receipt:RetainedCloneProgress,work:usize,last_work:u64,complete:bool,closing:bool,output:Option<Vec<u8>>,child_refusal:Option<ValueError>,bookkeeping_refusal:Option<ValueError>,
}
impl FlowTraceCursor{
 pub(crate) fn new()->Self{Self{identity:None,phase:0,width:0,height:0,threshold:0.0,epsilon:0.0,mask_length:0,at:0,mask:Vec::new(),tracer:None,trace_close:None,segments:Vec::new(),encoding:None,fault:None,fault_part:0,fault_at:0,message:String::new(),owners:None,pending:RetirementDemand{depth:1,..Default::default()},receipt:Default::default(),last_receipt:Default::default(),work:0,last_work:0,complete:false,closing:false,output:None,child_refusal:None,bookkeeping_refusal:None}}
 pub(crate) fn next_work_demand(&self)->RetirementDemand{self.pending}
 pub(crate) fn last_turn_work(&self)->u64{self.last_work}
 pub(crate) fn retained_receipt(&self)->RetainedCloneProgress{self.receipt}
 pub(crate) fn work_receipt(&self)->usize{self.work}
 fn record(&mut self,receipt:RetainedCloneProgress,cpu:u64)->Result<(),ValueError>{self.last_receipt=receipt;self.last_work=cpu;self.receipt=self.receipt.checked_add(receipt)?;self.work=self.work.checked_add(usize::try_from(cpu).map_err(|_|refusal("Original Flow trace CPU exceeds native width"))?).ok_or_else(||refusal("Original Flow trace CPU overflow"))?;Ok(())}
 fn step(&mut self,args:&FlowArguments,identity:(u64,u64),work:&mut RetainedWorkLedger,effect:&mut semio_framework_value::RetainedAllocationEffect<'_>)->Result<TraceStep,ValueError>{match self.phase{
  0=>{self.identity=Some(identity);self.phase=1;Ok(TraceStep::work(1))},
  1=>{self.last_work=1;self.width=u32_arg(args,"width")?;self.height=u32_arg(args,"height")?;self.threshold=f64_arg(args,"threshold")?;self.epsilon=f64_arg(args,"simplifyEpsilon")?;let span=args.get("mask").ok_or_else(||refusal("Original trace mask absent"))?;let mask=args.bytes(span);self.mask_length=mask.len();let input=BitmapTraceInput{width:self.width,height:self.height,mask,threshold:self.threshold,simplify_epsilon:self.epsilon,max_pixels:16777216,max_edges:65536,max_segments:65536,max_work:100000000};if let Err(error)=BitmapTraceJob::validate_input(&input){self.fault=Some((true,fault_message(error)));self.phase=7;}else{self.phase=2;}Ok(TraceStep::work(1))},
  2=>{self.last_work=1;if self.at==self.mask_length{self.tracer=Some(BitmapTraceJob::new(BitmapTraceInput{width:self.width,height:self.height,mask:std::mem::take(&mut self.mask),threshold:self.threshold,simplify_epsilon:self.epsilon,max_pixels:16777216,max_edges:65536,max_segments:65536,max_work:100000000}));self.at=0;self.phase=3;return Ok(TraceStep::work(1));}let before=work.receipt();if !slot(&mut self.mask,work,effect)?{return Ok(TraceStep::work(u64::from(work.receipt()!=before)));}let span=args.get("mask").ok_or_else(||refusal("Original trace mask absent"))?;let source=args.bytes(span);if source.len()!=self.mask_length{return Err(refusal("Original Flow trace mask extent changed"));}let value=source[self.at];work.vec_push(&mut self.mask,value).map_err(|(error,_)|refusal(error))?;self.at+=1;Ok(TraceStep::work(1))},
  3=>{let child=self.tracer.as_mut().ok_or_else(||refusal("Flow trace lost its working state"))?;let result=child.advance(1,work,effect);let cpu=child.last_turn_work();self.pending=child.next_work_demand();match result{Ok(progress)=>{if progress.done{self.phase=4;}},Err(error)=>{self.fault=Some((false,fault_message(error)));self.phase=7;}}Ok(TraceStep::work(cpu))},
  4=>{self.last_work=1;let output=self.tracer.as_ref().ok_or_else(||refusal("Flow trace lost its working state"))?.result().map_err(|_|refusal("Completed Flow trace output disappeared"))?;if self.at==output.len(){self.encoding=Some(ArtifactCanonicalJsonTreeWireCursor::new(TraceWire::Success{segments:std::mem::take(&mut self.segments)}));self.phase=5;return Ok(TraceStep::work(1));}let before=work.receipt();if !slot(&mut self.segments,work,effect)?{return Ok(TraceStep::work(u64::from(work.receipt()!=before)));}let segment=match output[self.at]{PathSegment::Move{to}=>TraceSegment::Move{to},PathSegment::Line{to}=>TraceSegment::Line{to},PathSegment::Close=>TraceSegment::Close,_=>return Err(refusal("Canonical Flow trace emitted a curve"))};work.vec_push(&mut self.segments,segment).map_err(|(error,_)|refusal(error))?;self.at+=1;Ok(TraceStep::work(1))},
  5=>{let encoding=self.encoding.as_mut().ok_or_else(||refusal("Flow trace lost its working state"))?;let grant=work.child_grant();let d=encoding.next_demand(grant.maximum_copy_bytes)?;if !permits(grant,d){work.require_child(d).map_err(refusal)?;return Ok(TraceStep::work(0));}let maximum=effect.remaining_work_units()?;let result=encoding.advance(&mut effect.reborrow(grant,maximum)?);self.last_work=encoding.last_turn_work();let receipt=match &result{Ok(step)=>step.progress,Err(error)=>error.retained_progress()};let posted=work.consume_child(receipt).map_err(refusal);let step=match result{Err(error)=>{if let Err(posting)=posted{self.child_refusal=Some(posting);}return Err(error);},Ok(step)=>step};if let Some(output)=step.output{self.output=Some(output);self.phase=6;}posted?;Ok(TraceStep::work(self.last_work))},
  6=>{self.complete=true;Ok(TraceStep::work(1))},
  7=>{self.last_work=1;let(input,message)=self.fault.ok_or_else(||refusal("Flow trace lost its fault"))?;let prefix=if input{"invalid input: "}else{"operation failed: "};let total=prefix.len().checked_add(message.len()).ok_or_else(||refusal("Flow trace diagnostic extent overflow"))?;let before=work.receipt();if !work.reserve_string(&mut self.message,total,effect.actual()).map_err(refusal)?{return Ok(TraceStep::work(u64::from(work.receipt()!=before)));}if self.fault_part==2{self.encoding=Some(ArtifactCanonicalJsonTreeWireCursor::new(TraceWire::Failure{error:std::mem::take(&mut self.message)}));self.phase=5;return Ok(TraceStep::work(1));}let part=if self.fault_part==0{prefix}else{message};if self.fault_at==part.len(){self.fault_at=0;self.fault_part+=1;return Ok(TraceStep::work(1));}let mut end=(self.fault_at+64).min(part.len());while !part.is_char_boundary(end){end-=1;}if !work.string_push(&mut self.message,&part[self.fault_at..end]).map_err(refusal)?{return Ok(TraceStep::work(0));}self.fault_at=end;Ok(TraceStep::work(1))},
  _=>Ok(TraceStep::work(0)),
 }}
 pub(crate) fn advance_original(&mut self,args:&FlowArguments,cx:&mut semio_framework_job::StepContext<'_>)->Result<FlowFeatureStep,FlowFailure>{
  self.last_work=0;self.last_receipt=Default::default();cx.original_source_parent().map_err(|error|FlowFailure::from_value(AbiErrorCode::NoCredit,error))?;if cx.is_cancelled(){self.begin_close();return Err(abi_refusal(AbiErrorCode::Cancelled));}if cx.should_yield()||self.closing||self.complete||cx.fuel_remaining()==0{return Ok(FlowFeatureStep::Yield);}let identity=(cx.operation().0,cx.generation().0);if self.identity.is_some_and(|prior|prior!=identity){return Err(FlowFailure::from_value(AbiErrorCode::StaleGeneration,refusal("Original Flow trace caller changed business identity")));}
  let mut work=RetainedWorkLedger::new(cx.retained_grant());if !work.admits_absolute(self.pending){work.require_absolute(self.pending);return Ok(FlowFeatureStep::Yield);}let Some(root)=work.enter()else{self.pending=work.next_demand();return Ok(FlowFeatureStep::Yield);};if !work.can_step(){work.exit();return Ok(FlowFeatureStep::Yield);}let grant=cx.retained_grant();let funded=match cx.with_original_effect(grant,|_,effect|self.step(args,identity,&mut work,effect)){Ok(funded)=>funded,Err(error)=>{work.exit();return Err(FlowFailure::from_value(AbiErrorCode::NoCredit,error))}};let Some((result,performed))=funded else{work.exit();return Ok(FlowFeatureStep::Yield)};let cpu=match &result{Ok(step)=>step.cpu,Err(_)=>self.last_work};if cpu>0{work.note_source(root);}self.pending=work.next_demand();work.exit();let receipt=work.receipt();let posted=cx.consume_retained(receipt);if performed==0{cx.consume_fuel(cpu)}let recorded=self.record(receipt,cpu);match result{Err(error)=>{if let Err(bookkeeping)=recorded{self.bookkeeping_refusal=Some(bookkeeping);}let secondary=match posted{Err(posting)=>Some(posting),Ok(())=>self.child_refusal.take()};self.begin_close();Err(FlowFailure::from_value(AbiErrorCode::Busy,error).with_retained_progress(receipt).with_receipt_refusal(secondary))},Ok(_)=>{if let Err(error)=recorded{self.begin_close();return Err(FlowFailure::from_value(AbiErrorCode::LimitExceeded,error).with_retained_progress(receipt).with_receipt_refusal(posted.err()));}if let Err(error)=posted{self.begin_close();return Err(FlowFailure::from_value(AbiErrorCode::NoCredit,error).with_retained_progress(receipt));}Ok(if self.complete{FlowFeatureStep::Complete(self.output.take().ok_or_else(||FlowFailure::from_value(AbiErrorCode::Busy,refusal("Completed original trace output is absent")))?)}else{FlowFeatureStep::Progress{completed:self.at.min(self.mask_length)as u64,total:self.mask_length as u64}})}}
 }
 pub(crate) fn begin_close(&mut self){self.closing=true;if let Some(encoding)=self.encoding.as_mut(){encoding.begin_close();}}
 pub(crate) fn terminal_is_empty(&self)->bool{self.encoding.is_none()&&self.tracer.is_none()&&self.trace_close.is_none()&&self.owners.is_none()&&self.mask.capacity()==0&&self.segments.capacity()==0&&self.message.capacity()==0&&self.output.is_none()&&self.child_refusal.is_none()&&self.bookkeeping_refusal.is_none()}
 pub(crate) fn next_close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if let Some(encoding)=self.encoding.as_ref(){return if encoding.terminal_is_empty(){Ok(RetirementDemand{depth:1,..Default::default()})}else{encoding.next_demand(body)}}if let Some(owner)=self.trace_close.as_ref(){return if owner.terminal_is_empty(){Ok(RetirementDemand{depth:1,..Default::default()})}else{owner.next_demand(body)}}if let Some(owner)=self.owners.as_ref(){return if owner.terminal_is_empty(){Ok(RetirementDemand{depth:1,..Default::default()})}else{owner.next_demand(body)}}Ok(RetirementDemand{depth:usize::from(!self.terminal_is_empty()),..Default::default()})}
 pub(crate) fn close_step(&mut self,effect:&mut semio_framework_value::RetainedAllocationEffect<'_>)->Result<bool,ValueError>{
  let grant=effect.grant();self.last_work=0;self.last_receipt=Default::default();self.begin_close();if self.terminal_is_empty(){return Ok(true);}let d=self.next_close_demand(grant.maximum_copy_bytes)?;if !permits(grant,d){return Ok(false);}let result:Result<(RetainedCloneProgress,u64),ValueError>=(||{
   if let Some(encoding)=self.encoding.as_mut(){if encoding.terminal_is_empty(){self.encoding=None;return Ok((RetainedCloneProgress{copied_items:1,..Default::default()},1));}let original=encoding.close_step(effect);self.last_work=encoding.last_turn_work();return original.map(|receipt|(receipt,self.last_work));}
   if let Some(owner)=self.trace_close.as_mut(){if owner.terminal_is_empty(){self.trace_close=None;return Ok((RetainedCloneProgress{copied_items:1,..Default::default()},1));}let original=semio_os_flow_host_core::poll_close_step(owner.step(grant.maximum_copy_bytes,effect));self.last_work=u64::try_from(owner.last_turn_work()).unwrap_or(u64::MAX);return original.map(|step|(step.progress(),self.last_work));}
   if let Some(tracer)=self.tracer.take(){self.trace_close=Some(ControlledRetirement::retain(tracer));return Ok((RetainedCloneProgress{copied_items:1,..Default::default()},1));}
   if let Some(owner)=self.owners.as_mut(){if owner.terminal_is_empty(){self.owners=None;return Ok((RetainedCloneProgress{copied_items:1,..Default::default()},1));}let original=semio_os_flow_host_core::poll_close_step(owner.step(grant.maximum_copy_bytes,effect));self.last_work=u64::try_from(owner.last_turn_work()).unwrap_or(u64::MAX);return original.map(|step|(step.progress(),self.last_work));}
   self.owners=Some(ControlledRetirement::retain(TraceOwners{mask:std::mem::take(&mut self.mask),segments:std::mem::take(&mut self.segments),message:std::mem::take(&mut self.message),output:self.output.take(),child_refusal:self.child_refusal.take(),bookkeeping_refusal:self.bookkeeping_refusal.take()}));Ok((RetainedCloneProgress{copied_items:1,..Default::default()},1))
  })();let(receipt,cpu)=match &result{Ok(step)=>*step,Err(error)=>(error.retained_progress(),self.last_work)};let recorded=self.record(receipt,cpu);match result{Err(error)=>{if let Err(bookkeeping)=recorded{self.bookkeeping_refusal=Some(bookkeeping);}Err(error)},Ok(_)=>{recorded?;Ok(false)}}
 }
 pub(crate) fn close_original(&mut self,cx:&mut semio_framework_job::StepContext<'_>)->Result<bool,FlowFailure>{self.last_work=0;self.last_receipt=Default::default();cx.original_source_parent().map_err(|error|FlowFailure::from_value(AbiErrorCode::NoCredit,error))?;if cx.fuel_remaining()==0{return Ok(false);}if self.identity.is_some_and(|identity|identity!=(cx.operation().0,cx.generation().0)){return Err(FlowFailure::from_value(AbiErrorCode::StaleGeneration,refusal("Original Flow trace close changed business identity")));}let funded=cx.with_original_effect(cx.retained_grant(),|_,effect|self.close_step(effect)).map_err(|error|FlowFailure::from_value(AbiErrorCode::NoCredit,error))?;let Some((result,performed))=funded else{return Ok(false)};let posted=cx.consume_retained(self.last_receipt);if performed==0{cx.consume_fuel(self.last_work)}match result{Err(error)=>Err(FlowFailure::from_value(AbiErrorCode::Busy,error).with_retained_progress(self.last_receipt).with_receipt_refusal(posted.err())),Ok(done)=>{posted.map_err(|error|FlowFailure::from_value(AbiErrorCode::NoCredit,error).with_retained_progress(self.last_receipt))?;Ok(done)}}}

}
impl Drop for FlowTraceCursor{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"Original Flow trace dropped before paid owner closure");}}
